def dolbear(n):
    return 50 + (n - 40) / 4.0
for n in (60, 100, 140):
    print('%d chirps per minute: %.1f degrees F' % (n, dolbear(n)))

v = 343.0
for d in (1.0, 2.0, 4.0):
    print('Target %.1f m: echo delay %.2f ms' % (d, 2 * d / v * 1000.0))

def ndsi(bio, anth):
    return (bio - anth) / (bio + anth)
for bio, anth in ((0.9, 0.1), (0.5, 0.5), (0.1, 0.9)):
    print('Bio %.1f, anth %.1f: NDSI %.2f' % (bio, anth, ndsi(bio, anth)))

for rate in (48000, 192000):
